mapper.select:
SELECT *
FROM activity
WHERE id = #{activityId}
  AND user_id = #{userId}
  AND deleted_at IS NULL

SELECT id, title, category, organizer, audience_scope, enroll_deadline, published_at, location,max_participants,
CASE WHEN NOW() < enroll_deadline THEN 2 WHEN NOW() >= start_time AND NOW() < end_time THEN 3 WHEN NOW() >= end_time THEN 4 WHEN status = 5 THEN 5 ELSE 0 END AS status
FROM activity WHERE status = #{status} AND deleted_at IS NULL
AND category = #{category}
AND MATCH(title, content, organizer) AGAINST(#{keyword} IN BOOLEAN MODE)
AND id < #{lastId}
ORDER BY id, published_at DESC LIMIT #{limit}
